2.8 log2FC shrinkage


Code
# Tutorial: log2FC distribution before vs after apeglm shrinkage
p_shrink &lt;- fits |&gt;
  transmute(tissue, d = map(de, \(d) d |&gt;
                               dplyr::select(before = log2FoldChange, after = log2FoldChange_shrunk) |&gt;
                               pivot_longer(everything(), names_to = "shrinkage", values_to = "lfc"))) |&gt;
  unnest(d) |&gt;
  mutate(shrinkage = factor(shrinkage, levels = c("before", "after"))) |&gt;
  ggplot(aes(lfc, colour = shrinkage)) +
  geom_density(linewidth = 0.4, na.rm = TRUE) +
  facet_wrap(~ tissue) +
  coord_cartesian(xlim = c(-3, 3)) +
  scale_colour_manual(values = c(before = "grey50", after = "black")) +
  labs(x = "log2 fold change (Cre / GFP)", y = "Density", colour = "LFC shrinkage") +
  theme_bulk()
