5.2 Leave-one-out robustness of GO terms


Code
# Robustness of each primary GSEA term:
#  - leave-one-out: GSEA rerun on the primary model refit without each 2025-10 GFP mouse
#    (fits$fit[[.]]$loo); must stay significant, same NES sign;
#  - within-run direction: GSEA on the 2025-10-only Cre vs GFP fold changes; NES must have the
#    same sign (direction only; that comparison has 3 GFP).
# gseGO is run with every term returned (pvalueCutoff = 1) so missing terms are real misses.
gsea_all &lt;- function(lfc_tbl, ont)
  gseGO(geneList = ranked_genes(map_entrez(lfc_tbl)), OrgDb = org.Mm.eg.db, ont = ont,
        keyType = "ENTREZID", minGSSize = 15, maxGSSize = 500, pvalueCutoff = 1, eps = 0,
        seed = TRUE, verbose = FALSE) |&gt;
  as.data.frame()

lfc_table &lt;- function(res, lfc)
  as_tibble(as.data.frame(res), rownames = "ensemblID") |&gt;
  mutate(log2FoldChange_shrunk = lfc) |&gt;
  left_join(dplyr::select(id2name, ensemblID, Symbol), by = "ensemblID")

fit_of &lt;- set_names(fits$fit, fits$tissue)

gsea_loo &lt;- gsea |&gt;
  dplyr::filter(n_sig &gt; 0) |&gt;
  dplyr::select(tissue, ont, res) |&gt;
  mutate(loo = map2(tissue, ont, \(t, o)
           imap(fit_of[[t]]$loo, \(l, b) gsea_all(lfc_table(l$res, l$lfc), o) |&gt;
                  transmute(ID, NES_loo = NES, padj_loo = p.adjust, dropped = b)) |&gt;
             bind_rows() |&gt; (\(x) if (nrow(x)) x else
               tibble(ID = character(), NES_loo = double(), padj_loo = double(), dropped = character()))()),
         within = map2(tissue, ont, \(t, o) {
           w &lt;- fit_of[[t]]$within
           gsea_all(lfc_table(w, w$log2FoldChange), o) |&gt; transmute(ID, NES_within = NES)
         }),
  robust = pmap(list(res, loo, within), \(r, l, w) {
    n_fits &lt;- n_distinct(l$dropped)
    as.data.frame(r) |&gt;
      dplyr::select(ID, Description, NES, p.adjust) |&gt;
      left_join(l, by = "ID") |&gt;
      group_by(ID, Description, NES, p.adjust) |&gt;
      summarise(n_loo = sum(!is.na(padj_loo)),
                loo_max_padj = suppressWarnings(max(padj_loo, na.rm = TRUE)),
                loo_same_sign = all(sign(NES_loo) == sign(NES[1]), na.rm = TRUE),
                drivers = paste(dropped[!is.na(dropped) & (is.na(padj_loo) | padj_loo &gt;= PADJ_CUT |
                                          sign(NES_loo) != sign(NES[1]))], collapse = ";"),
                .groups = "drop") |&gt;
      left_join(w, by = "ID") |&gt;
      mutate(within_same_sign = sign(NES_within) == sign(NES),
             loo_ok = n_fits == 0 |
               (n_loo == n_fits & loo_same_sign & loo_max_padj &lt; PADJ_CUT),
             robust = loo_ok & within_same_sign %in% TRUE) |&gt;
      arrange(desc(robust), p.adjust)
  }))

pwalk(dplyr::select(gsea_loo, tissue, ont, robust), \(tissue, ont, robust)
      write_tsv(robust, file.path(CSV_DIR, "pathway",
                                  sprintf("%s_gseGO_%s_loo_robustness.tsv", tolower(tissue), ont))))
gsea_loo |&gt; transmute(tissue, ont, n_terms = map_int(robust, nrow),
                      n_robust = map_int(robust, \(r) sum(r$robust)))

6.3 Pathways
Pathways. Two complementary views:

APOE-liver sets. GSEA of each set on the Wald statistic of every contrast that bears on the switch: main, 2025-10 only, within-Cre dose, germline E2 vs E4, and brain as the negative control. FDR is controlled within the small family (a priori / from this data), not across all of GO. Testing a few hypothesis-driven sets is the standard way to keep power, provided the sets are fixed before looking.
Genome-wide GO near-misses. Terms with |NES| ≥ 1.5 and 0.05 ≤ FDR &lt; 0.25 in the main liver GSEA, with leave-one-out and 2025-10-only direction. Subramanian et al. (2005) recommend FDR &lt; 0.25 for exploratory GSEA.

Caveat: preranked GSEA permutes genes, not samples. It ignores correlation between genes, so its p values are optimistic for sets of co-regulated genes (Wu & Smyth 2012). Agreement across contrasts is a better guide than any single p value.


Code
# 1. APOE-liver sets: GSEA on the Wald statistic (signed, scaled by uncertainty) of every contrast
#    that bears on the switch, so each set is read against the same lines of evidence as a gene.
#    FDR is controlled within each family (a priori / this data), not across all of GO: a small,
#    pre-specified family is the standard way to keep power for hypothesis-driven sets.
set_t2g &lt;- apoe_sets |&gt; dplyr::select(set, genes) |&gt; unnest(genes) |&gt; dplyr::rename(gene = genes)
stat_rank &lt;- function(r) {
  s &lt;- set_names(r$stat, rownames(r))
  sort(s[!is.na(s)], decreasing = TRUE)
}
gsea_sets &lt;- function(r, contrast) {
  g &lt;- clusterProfiler::GSEA(stat_rank(r), TERM2GENE = set_t2g, pvalueCutoff = 1, minGSSize = 5,
                             maxGSSize = 2000, eps = 0, seed = TRUE, verbose = FALSE) |&gt;
    as.data.frame()
  tibble(set = g$ID, NES = g$NES, pvalue = g$pvalue, setSize = g$setSize,
         leading_edge = map_chr(str_split(g$core_enrichment, "/"),
                                \(x) paste(na.omit(id2name$Symbol[match(x, id2name$ensemblID)]), collapse = "/")),
         contrast = contrast)
}
liver_fit &lt;- fits$fit[[match("Liver", fits$tissue)]]
germ_liver &lt;- germline$res[[which(germline$tissue == "Liver" & germline$a == "E2" & germline$b == "E4")]]
SET_CONTRASTS &lt;- c("Cre vs GFP (main)", "Cre vs GFP (2025-10 only)", "Dose: E2 fraction (Cre only)",
                   "Germline E2 vs E4", "Brain Cre vs GFP (neg. control)")
set_gsea &lt;- list(liver_fit$res, liver_fit$within, dose_gene_res("Liver"), germ_liver,
                 fits$fit[[match("Brain", fits$tissue)]]$res) |&gt;
  map2(SET_CONTRASTS, gsea_sets) |&gt; bind_rows() |&gt;
  left_join(dplyr::select(APOE_LIVER_SETS, set, basis), by = "set") |&gt;
  group_by(contrast, basis) |&gt; mutate(padj_family = p.adjust(pvalue, "BH")) |&gt; ungroup()
# leave-one-GFP-out for the main contrast: does the set keep its sign?
set_loo &lt;- imap(liver_fit$loo, \(l, k) gsea_sets(l$res, k)) |&gt; bind_rows() |&gt;
  group_by(set) |&gt; summarise(loo_min_abs_NES = min(abs(NES)), loo_signs = list(sign(NES)), .groups = "drop")
set_tbl &lt;- set_gsea |&gt; dplyr::filter(contrast == SET_CONTRASTS[1]) |&gt;
  left_join(set_loo, by = "set") |&gt;
  mutate(loo_same_sign = map2_lgl(loo_signs, NES, \(s, n) all(s == sign(n)))) |&gt;
  dplyr::select(-loo_signs) |&gt;
  left_join(set_gsea |&gt; dplyr::filter(contrast != SET_CONTRASTS[1]) |&gt;
              dplyr::select(set, contrast, NES) |&gt;
              pivot_wider(names_from = contrast, values_from = NES, names_prefix = "NES: "), by = "set")
write_csv(set_tbl, file.path(CSV_DIR, "pathway", "apoe_liver_sets_main_with_checks.csv"))
write_csv(set_gsea, file.path(CSV_DIR, "pathway", "apoe_liver_sets_gsea_all_contrasts.csv"))
set_tbl |&gt; dplyr::select(basis, set, setSize, NES, pvalue, padj_family, loo_same_sign) |&gt;
  mutate(across(where(is.numeric), \(x) signif(x, 2)))







Code
# 2. genome-wide GO near-misses: |NES| &gt;= ES_NES and PADJ_CUT &lt;= padj &lt; ES_GSEA_FDR in the main
#    liver GSEA (same ranking as PATHWAY ANALYSIS: shrunk log2FC), with leave-one-out and 2025-10-
#    only direction. GSEA's authors recommend FDR &lt; 0.25 for exploratory, hypothesis-generating use.
near_miss &lt;- map(c("BP", "MF", "CC"), \(o) {
  main &lt;- gsea_all(lfc_table(liver_fit$res, liver_fit$resLFC$log2FoldChange), o)
  loo  &lt;- imap(liver_fit$loo, \(l, k) gsea_all(lfc_table(l$res, l$lfc), o) |&gt;
                 transmute(ID, NES_loo = NES, dropped = k)) |&gt; bind_rows()
  w    &lt;- gsea_all(lfc_table(liver_fit$within, liver_fit$within$log2FoldChange), o) |&gt;
    transmute(ID, NES_within = NES)
  main |&gt; dplyr::filter(abs(NES) &gt;= ES_NES, p.adjust &gt;= PADJ_CUT, p.adjust &lt; ES_GSEA_FDR) |&gt;
    transmute(ont = o, ID, Description, setSize, NES, pvalue, p.adjust,
              leading_edge = map_chr(str_split(core_enrichment, "/"), \(x)
                paste(na.omit(suppressMessages(mapIds(org.Mm.eg.db, x, "SYMBOL", "ENTREZID"))), collapse = "/"))) |&gt;
    left_join(loo |&gt; group_by(ID) |&gt; summarise(n_loo = n(), loo_same_sign_n = list(sign(NES_loo)),
                                               .groups = "drop"), by = "ID") |&gt;
    left_join(w, by = "ID") |&gt;
    mutate(loo_same_sign = map2_lgl(loo_same_sign_n, NES, \(s, n) length(s) == length(liver_fit$loo) &&
                                      all(s == sign(n))),
           within_same_sign = sign(NES_within) == sign(NES)) |&gt;
    dplyr::select(-loo_same_sign_n)
}) |&gt; bind_rows() |&gt; arrange(p.adjust)
write_csv(near_miss, file.path(CSV_DIR, "pathway", "liver_gseGO_near_miss.csv"))
near_miss |&gt; dplyr::count(ont, loo_same_sign, within_same_sign)







